class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Check every possible substring of length k
        for i in range(n - k + 1):
            # Check if all characters in s[i:i+k] are the same
            char = s[i]
            valid = True
            # Check all characters in the substring are the same
            for j in range(i, i + k):
                if s[j] != char:
                    valid = False
                    break
            if not valid:
                continue
            # Check the character before (if exists) is different
            if i > 0 and s[i - 1] == char:
                continue
            # Check the character after (if exists) is different
            if i + k < n and s[i + k] == char:
                continue
            return True
        return False
