class Solution:
    def findValidPair(self, s: str) -> str:
        from collections import Counter
        count = Counter(s)
        for i in range(len(s) - 1):
            d1, d2 = s[i], s[i + 1]
            if d1 != d2 and count[d1] == int(d1) and count[d2] == int(d2):
                return d1 + d2
        return ""
