class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            # Check if index i-k exists and if nums[i] > nums[i-k]
            # Check if index i+k exists and if nums[i] > nums[i+k]
            # If neither index exists, it's still good.
            # So we need to check:
            # - If i-k exists, then nums[i] must be > nums[i-k]
            # - If i+k exists, then nums[i] must be > nums[i+k]
            # If both indices don't exist, it's automatically good.

            left_ok = True
            right_ok = True

            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    left_ok = False
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    right_ok = False

            if left_ok and right_ok:
                total += nums[i]

        return total
